'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);

let idx = 0;
const N = Number(input[idx++]);
const D = Number(input[idx++]);

const positions = new Array(N);
const charges = new Array(N);

for (let i = 0; i < N; i++) {
  positions[i] = Number(input[idx++]);
  charges[i] = Number(input[idx++]);
}

const dp = new Array(N).fill(Infinity);
dp[0] = 0;

for (let j = 1; j < N; j++) {
  for (let i = 0; i < j; i++) {
    const distance = positions[j] - positions[i];
    dp[j] = Math.min(dp[j], dp[i] + distance * distance / charges[i]);
  }
}

let answer = Infinity;
for (let i = 0; i < N; i++) {
  const distance = D - positions[i];
  answer = Math.min(answer, dp[i] + distance * distance / charges[i]);
}

console.log(answer.toFixed(3));
